// ---- Pick the run to draft and gather everything the draft needs ----
const cfg = Object.fromEntries($('Read config').all(0, 0).map(i => [i.json.key, String(i.json.value ?? '')]));
const runs = $('Read runs').all(0, 0).map(i => i.json);
const explainers = $('Read explainers').all(0, 0).map(i => i.json);
const sources = $('Read sources').all(0, 0).map(i => i.json);

let runId = '';
try { runId = String($('When called by orchestrator').first().json.run_id || ''); } catch (e) {}
const draftable = r => ['analysed', 'draft_failed', 'draft_ready'].includes(String(r.status));
const run = runId ? runs.find(r => r.run_id === runId)
                  : runs.filter(draftable).sort((a, b) => String(b.updated_at).localeCompare(String(a.updated_at)))[0];
if (!run) throw new Error(`No run to draft${runId ? ' for ' + runId : ''}. Run the Analyse workflow first.`);
if (!draftable(run)) throw new Error(`Run ${run.run_id} has status "${run.status}" – it must be analysed before drafting.`);
if (!run.fee_code) throw new Error(`Run ${run.run_id} has no fee issue; nothing to explain.`);

const exp = explainers
  .filter(e => e.fee_code === run.fee_code && String(e.status) === 'approved')
  .sort((a, b) => String(b.version).localeCompare(String(a.version), undefined, { numeric: true }))[0];
if (!exp) throw new Error(`No approved explainer for ${run.fee_code}. Add one to the explainers tab first.`);

// Approved explainer text is reused verbatim, except its review date range, which follows this run's window.
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const ymd = v => { const [y, m, d] = String(v).slice(0, 10).split('-').map(Number); return { y, m, d }; };
const a = ymd(run.window_from), b = ymd(run.window_to);
const range = a.y && b.y ? `from ${a.d} ${MON[a.m - 1]}${a.y !== b.y ? ' ' + a.y : ''} to ${b.d} ${MON[b.m - 1]} ${b.y}` : '';
const RANGE_RE = /\bfrom \d{1,2} [A-Z][a-z]{2,8}(?: \d{4})? to \d{1,2} [A-Z][a-z]{2,8} \d{4}\b/g;
const bullets = JSON.parse(exp.bullets_json).map(t => range ? String(t).replace(RANGE_RE, range) : t);

const srcs = sources.filter(s => s.fee_code === run.fee_code && String(s.active).toUpperCase() === 'TRUE');
const stats = JSON.parse(run.theme_stats_json);
const quotes = JSON.parse(run.quotes_json);
return [{ json: {
  run_id: run.run_id, week_start: run.week_start, week_end: run.week_end,
  window_from: run.window_from, window_to: run.window_to, base_n: Number(run.base_n),
  top_themes: String(run.top_themes).split(',').filter(Boolean),
  fee_code: run.fee_code, fee_count: Number(run.fee_count), fee_trend: run.fee_trend,
  stats, quotes,
  explainer: { version: exp.version, bullets, urls: String(exp.source_urls).split(/\s+/).filter(Boolean) },
  sources: srcs.map(s => ({ url: s.url, title: s.title, publisher: s.publisher })),
  cfg: { word_limit: Number(cfg.pulse_word_limit || 250), max_themes: Number(cfg.max_themes || 5), max_bullets: Number(cfg.max_explainer_bullets || 6),
         allowed_domains: String(cfg.allowed_source_domains || '').split(',').map(s => s.trim()).filter(Boolean),
         writing_model: /\d/.test(cfg.writing_model || '') ? cfg.writing_model : 'claude-sonnet-5-5', timezone: cfg.timezone || 'Asia/Kolkata' },
}}];

// one item per official source URL to fetch
const ctx = $('Prepare context').first().json;
return ctx.explainer.urls.map(url => ({ json: { url } }));

// ---- Check that the official pages still state the facts the explainer relies on ----
// Key-fact check (stable) instead of a whole-page hash (pages show changing "Updated x days ago" text).
const KEY_FACTS = {
  'help.openai.com':        [/transfer/i, /Google Play/i, /refund/i],
  'support.google.com':     [/Budget\s*(&|&amp;|and)\s*history/i, /developer/i, /refund/i],
  'developer.android.com':  [/three days|3 days/i, /PENDING/, /refund/i],
};
const urls = $('List sources').all().map(i => i.json.url);
const today = new Date(Date.now() + 5.5 * 3600e3).toISOString().slice(0, 10);
const rows = $input.all().map((item, idx) => {
  const j = item.json;
  const url = urls[idx];
  const host = (String(url).match(/^https?:\/\/([^\/?#:]+)/i) || [])[1] || '';   // no URL() in n8n sandbox
  const code = Number(j.statusCode ?? (j.error ? 0 : 200));
  const body = String(j.body ?? j.data ?? '');
  const text = body.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ');
  const facts = KEY_FACTS[host] || [];
  const found = facts.filter(re => re.test(text)).length;
  let status;
  if (!body || code >= 400 || j.error) status = 'unreachable';          // blocked / down → can't verify this week
  else if (!facts.length) status = 'fetched_no_check';
  else status = found === facts.length ? 'verified' : 'facts_missing';  // page changed → needs human review
  return { url, last_fetched: today, content_hash: `facts ${found}/${facts.length}`, fetch_status: status };
});
return rows.map(r => ({ json: r }));

// ---- Ask Claude for the prose only: theme one-liners, quote picks (verbatim excerpts), observation, 3 actions ----
const ctx = $('Prepare context').first().json;
const feeLabels = Object.fromEntries($('Read fee_types').all(0, 0).map(i => [i.json.fee_code, i.json.label]));
const pct = x => Math.round(Number(x) * 100);
const t = ctx.stats;
const m = String(ctx.fee_trend).match(/(\d+)\s*->\s*(\d+)\s*\(([\d.]+)%\s*->\s*([\d.]+)%.*\),\s*(\w+)/) || [];
const weeks = 10;
const facts = {
  week_end: ctx.week_end, window: `${ctx.window_from} to ${ctx.window_to}`, weeks, reviews_analysed: ctx.base_n,
  top_themes: ctx.top_themes.map(code => ({
    code, name: t.window[code].name,
    share_pct: pct(t.window[code].share), rated_1_2_star_pct: pct(t.window[code].neg_share),
    trend: t.trends[code].direction, first_half_pct: pct(t.trends[code].early_share), second_half_pct: pct(t.trends[code].late_share),
    this_week_pct: t.trends[code].this_week_share == null ? null : pct(t.trends[code].this_week_share),
  })),
  fee_issue: {
    code: ctx.fee_code, label: feeLabels[ctx.fee_code] || ctx.fee_code,
    reviews_in_window: ctx.fee_count, per_week_avg: Math.round(ctx.fee_count / weeks),
    first_half_count: Number(m[1] || 0), second_half_count: Number(m[2] || 0),
    first_half_share_of_low_star_billing_pct: Number(m[3] || 0), second_half_share_pct: Number(m[4] || 0),
    trend: m[5] || 'unknown', price_users_report_inr: 399,
  },
  quote_candidates: Object.fromEntries(Object.entries(ctx.quotes.themes).map(([k, v]) => [k, v.map(q => ({ review_id: q.review_id, rating: q.rating, text: q.text }))])),
  fee_quote_candidates: ctx.quotes.fee.map(q => ({ review_id: q.review_id, rating: q.rating, text: q.text })),
};

const system = `You write the prose parts of a weekly internal product pulse for the ChatGPT Android app (India), for a product team.
All numbers and quotes are inserted by code; you supply short text and choices only.

Return ONLY this JSON (no markdown fences):
{
 "theme_notes": {"<THEME_CODE>": "<max 9 words: what users complain about in this theme>", ... one per top theme},
 "quotes": {"<THEME_CODE>": {"review_id": "<id from that theme's candidates>", "excerpt": "<exact contiguous excerpt, 6-22 words>"}, ... one per top theme},
 "observation": "<max 50 words: what is going wrong or trending, centred on the fee issue>",
 "actions": [ {"title": "<max 6 words>", "detail": "<max 16 words>", "metric": "<numerator ÷ denominator>"} x3 ]
}

