  feedback = '\n\nYOUR PREVIOUS ANSWER FAILED THESE CHECKS – fix them:\n- ' + rep.failures.join('\n- ');
}
return [{ json: {
  attempt: feedback ? 2 : 1,
  facts,
  request: { model: ctx.cfg.writing_model, max_tokens: 2000, system,
    messages: [{ role: 'user', content: 'FACTS:\n' + JSON.stringify(facts, null, 1) + feedback }] },
}}];

