const pct = x => Math.round(Number(x) * 100);
const fmt = s => { const dt = new Date(s + 'T00:00:00Z'); return isNaN(dt) ? s : dt.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' }); };
const words = s => String(s).replace(/[#*_]/g, '').trim().split(/\s+/).filter(Boolean).length;
const top = ctx.top_themes;
const sentence = x => { const t = String(x || '').trim(); return t && !/[.!?]$/.test(t) ? t + '.' : t; };
const W = ctx.stats.window;

// --- quotes: must be exact excerpts of a candidate from the right theme
const quoteLines = [];
for (const code of top) {
  const q = d.quotes?.[code];
  const cand = (ctx.quotes.themes[code] || []).find(c => c.review_id === q?.review_id);
  const ex = String(q?.excerpt || '').trim();
  if (!cand) { failures.push(`Quote for ${code}: review_id not among that theme's candidates`); continue; }
  if (!ex || !cand.text.includes(ex)) { failures.push(`Quote for ${code}: excerpt is not an exact substring of review ${cand.review_id}`); continue; }
  const n = words(ex);
  if (n < 6 || n > 22) failures.push(`Quote for ${code}: excerpt has ${n} words (need 6–22)`);
  quoteLines.push(`- "${ex}" (${cand.rating}★, ${fmt(cand.date)})`);
}

