const bad = [...new Set((prose.replace(/(\d),(\d{3})/g, '$1$2').match(/\d+(\.\d+)?/g) || []).map(Number).filter(n => !allowed.has(n)))];
if (bad.length) failures.push(`Prose uses numbers not in FACTS: ${bad.join(', ')}`);
if (/doubl|spik|surg/i.test(prose) && facts.fee_issue.trend !== 'rising') failures.push('Prose describes a rise but the fee trend is ' + facts.fee_issue.trend);

