const offDomain = urls.filter(u => !allowedHosts.has(hostOf(u)));
if (offDomain.length) failures.push('Links not on official domains: ' + offDomain.join(', '));
const needsReview = verification.filter(v => v.fetch_status === 'facts_missing').map(v => v.url);
const unverified = verification.filter(v => v.fetch_status === 'unreachable').map(v => v.url);
const srcTitle = u => (ctx.sources.find(s => s.url === u) || {});
const expMd = [
  ...bullets.map(b => { const k = b.indexOf('. '); return k > 0 && k < 60 ? `- **${b.slice(0, k + 1)}** ${b.slice(k + 2)}` : `- ${b}`; }),
  '', '**Sources**', ...urls.map((u, i) => `${i + 1}. ${srcTitle(u).publisher || hostOf(u)}: [${srcTitle(u).title || u}](${u})`),
  '', `**Last checked: ${fmt(today)}**`,
].join('\n');
if (!/Last checked: /.test(expMd)) failures.push('Explainer missing "Last checked"');

const passed = failures.length === 0;
const report = {
  attempt, passed, failures, pulse_words: pulseWords,
  checks: { quotes_verbatim: quoteLines.length === 3, numbers_from_stats: bad.length === 0, actions: actions.length, explainer_bullets: bullets.length, official_links: urls.length },
  sources: verification.map(v => ({ url: v.url, status: v.fetch_status, facts: v.content_hash })),
  explainer_needs_review: needsReview, explainer_unverified: unverified,
};
const explainer = { fee_code: ctx.fee_code, version: ctx.explainer.version, bullets, source_links: urls, last_checked: today, needs_review: needsReview.length > 0, markdown: expMd };
return [{ json: {
  run_id: ctx.run_id,
  status: passed ? 'draft_ready' : (attempt === 1 ? 'needs_redraft' : 'draft_failed'),
  weekly_pulse: pulse,
  explainer_json: JSON.stringify(explainer),
  validation_report: JSON.stringify(report),
  error: passed ? '' : failures.join(' | ').slice(0, 500),
  updated_at: new Date(Date.now() + 5.5 * 3600e3).toISOString().slice(0, 19),
}}];

