if (actions.length !== 3) failures.push(`Need exactly 3 actions, got ${actions.length}`);
// a metric must be a named ratio: words on both sides of ÷, not raw numbers like "80 ÷ 1197"
const named = s => (String(s).match(/[A-Za-z]{3,}/g) || []).length >= 2;
actions.forEach((a, i) => {
  const parts = String(a.metric || '').split(/÷|\s\/\s/);
  if (parts.length !== 2 || !named(parts[0]) || !named(parts[1]))
    failures.push(`Action ${i + 1} metric must name what is counted on both sides, e.g. "Go purchases active in-app within 10 min ÷ Go purchases confirmed by Google Play" (got "${a.metric}")`);
});

// --- themes
if (top.length !== 3) failures.push(`Need 3 top themes, got ${top.length}`);
if (Object.keys(W).filter(k => k !== 'UNCLEAR').length > ctx.cfg.max_themes) failures.push('More than 5 themes');
for (const c of top) if (!d.theme_notes?.[c]) failures.push(`Missing theme note for ${c}`);

// --- assemble pulse (all numbers from stats)
const L = [];
L.push('# ChatGPT Android (India): Weekly Product Pulse');
L.push(`**Week ending ${fmt(ctx.week_end)}** · ${ctx.base_n} Google Play reviews, ${fmt(ctx.window_from)} – ${fmt(ctx.window_to)}`, '');
L.push('## Top themes');
top.forEach((c, i) => L.push(`${i + 1}. **${W[c].name}:** ${pct(W[c].share)}% of reviews, ${pct(W[c].neg_share)}% rated 1–2★. ${sentence(d.theme_notes?.[c])}`));
L.push('', '## What users say', ...quoteLines, '', '## Key observation', sentence(d.observation), '', '## Action ideas');
actions.forEach((a, i) => L.push(`${i + 1}. **${String(a.title).trim()}:** ${sentence(a.detail)}`, `   *Metric:* ${String(a.metric).trim()}`));
const pulse = L.join('\n');
const pulseWords = words(pulse);
if (pulseWords > ctx.cfg.word_limit) failures.push(`Pulse is ${pulseWords} words; limit ${ctx.cfg.word_limit}. Shorten by ${pulseWords - ctx.cfg.word_limit}+ words`);

// --- explainer (approved text, reused verbatim) + verification
const today = new Date(Date.now() + 5.5 * 3600e3).toISOString().slice(0, 10);
const bullets = ctx.explainer.bullets;
const urls = ctx.explainer.urls;
const hostOf = u => ((String(u).match(/^https?:\/\/([^\/?#:]+)/i) || [])[1] || '').toLowerCase();
const allowedHosts = new Set([...ctx.cfg.allowed_domains.map(s => s.toLowerCase()), ...ctx.sources.map(s => hostOf(s.url))].filter(Boolean));
if (bullets.length < 1 || bullets.length > ctx.cfg.max_bullets) failures.push(`Explainer has ${bullets.length} bullets (max ${ctx.cfg.max_bullets})`);
if (urls.length < 2) failures.push('Explainer needs at least 2 official links');
const offDomain = urls.filter(u => !allowedHosts.has(hostOf(u)));
if (offDomain.length) failures.push('Links not on official domains: ' + offDomain.join(', '));
const needsReview = verification.filter(v => v.fetch_status === 'facts_missing').map(v => v.url);
const unverified = verification.filter(v => v.fetch_status === 'unreachable').map(v => v.url);
const srcTitle = u => (ctx.sources.find(s => s.url === u) || {});
const expMd = [
  ...bullets.map(b => { const k = b.indexOf('. '); return k > 0 && k < 60 ? `- **${b.slice(0, k + 1)}** ${b.slice(k + 2)}` : `- ${b}`; }),
  '', '**Sources**', ...urls.map((u, i) => `${i + 1}. ${srcTitle(u).publisher || hostOf(u)}: [${srcTitle(u).title || u}](${u})`),
  '', `**Last checked: ${fmt(today)}**`,
].join('\n');
if (!/Last checked: /.test(expMd)) failures.push('Explainer missing "Last checked"');

const passed = failures.length === 0;
const report = {
  attempt, passed, failures, pulse_words: pulseWords,
  checks: { quotes_verbatim: quoteLines.length === 3, numbers_from_stats: bad.length === 0, actions: actions.length, explainer_bullets: bullets.length, official_links: urls.length },
  sources: verification.map(v => ({ url: v.url, status: v.fetch_status, facts: v.content_hash })),
  explainer_needs_review: needsReview, explainer_unverified: unverified,
};
const explainer = { fee_code: ctx.fee_code, version: ctx.explainer.version, bullets, source_links: urls, last_checked: today, needs_review: needsReview.length > 0, markdown: expMd };
return [{ json: {
  run_id: ctx.run_id,
  status: passed ? 'draft_ready' : (attempt === 1 ? 'needs_redraft' : 'draft_failed'),
  weekly_pulse: pulse,
  explainer_json: JSON.stringify(explainer),
  validation_report: JSON.stringify(report),
  error: passed ? '' : failures.join(' | ').slice(0, 500),
  updated_at: new Date(Date.now() + 5.5 * 3600e3).toISOString().slice(0, 19),
}}];
